// Build-time image pipeline: strips ALL metadata (EXIF/GPS included) and generates
// responsive, web-optimized copies from the raw source photos. Run via `npm run images`,
// or automatically before `dev`/`build` (see package.json). Safe to re-run — unchanged
// sources are skipped by comparing mtimes, so incremental runs stay fast.
//
// Output is derived/regenerated, not hand-maintained: never edit files under public/photos,
// public/trip, or src/data/generated by hand — edit this script or the source photos instead.

import { mkdir, readdir, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

async function pathExists(p) {
  try {
    await stat(p);
    return true;
  } catch {
    return false;
  }
}

const ROOT = path.resolve(import.meta.dirname, "..");
const PHOTOS_SRC = path.join(ROOT, "photos");
const TRIP_SRC = path.join(ROOT, "teslas-trip");
const PHOTOS_OUT = path.join(ROOT, "public", "photos");
const TRIP_OUT = path.join(ROOT, "public", "trip");
const MANIFEST_DIR = path.join(ROOT, "src", "data", "generated");

const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp"]);
const PHOTO_WIDTHS = [480, 800, 1280, 1920];
const TRIP_WIDTHS = [480, 1000, 1800];

// Excluded from the public gallery on purpose — see CLAUDE.md "Decisions locked in".
const EXCLUDED_PHOTOS = new Set(["tesla_2years_video.mp4"]);

/** Weak, filename-only signal for grouping + alt text. Never claims more than the filename
 * plausibly supports; falls back to a neutral caption per spec §27 when uncertain. */
const CATEGORY_RULES = [
  { test: /swim/i, category: "Swimming", alt: "Tesla swimming" },
  { test: /football|soccer/i, category: "Sports", alt: "Tesla playing football" },
  { test: /murchisonfalls/i, category: "Adventures", alt: "Tesla at Murchison Falls" },
  { test: /giraffe/i, category: "Adventures", alt: "Tesla on a family outing" },
  { test: /(^|_)bd(\.|_)/i, category: "Family", alt: "Tesla celebrating his birthday" },
  { test: /graduation/i, category: "Family", alt: "Tesla at his graduation day" },
  { test: /all_family/i, category: "Family", alt: "Tesla with his family" },
  { test: /daddy/i, category: "Family", alt: "Tesla with his dad" },
  { test: /amaani/i, category: "Cousins", alt: "Tesla with his cousin Amaani" },
  { test: /krystal/i, category: "Cousins", alt: "Tesla with his cousin Krystal" },
  { test: /leora/i, category: "Cousins", alt: "Tesla with his cousin Leora" },
  { test: /cousin/i, category: "Cousins", alt: "Tesla with a cousin" },
  { test: /excited_school/i, category: "Everyday Tesla", alt: "Tesla excited and ready for school" },
  { test: /driving/i, category: "Fun", alt: "Tesla — photo from his family collection" },
  { test: /animation/i, category: "Fun", alt: "Tesla — photo from his family collection" },
];

function categorize(filename) {
  for (const rule of CATEGORY_RULES) {
    if (rule.test.test(filename)) return { category: rule.category, alt: rule.alt };
  }
  return { category: "Everyday Tesla", alt: "Tesla — photo from his family collection" };
}

function slugify(filename) {
  return path
    .basename(filename, path.extname(filename))
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

async function isUpToDate(srcPath, outPath) {
  try {
    const [srcStat, outStat] = await Promise.all([stat(srcPath), stat(outPath)]);
    return outStat.mtimeMs >= srcStat.mtimeMs;
  } catch {
    return false;
  }
}

async function listImages(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile())
    .map((e) => e.name)
    .filter((name) => IMAGE_EXTENSIONS.has(path.extname(name).toLowerCase()))
    .filter((name) => !EXCLUDED_PHOTOS.has(name))
    .sort();
}

/** Strips all metadata (EXIF/GPS/ICC/etc.) unconditionally and writes one resized webp copy. */
async function renderSize(srcPath, outPath, width) {
  if (await isUpToDate(srcPath, outPath)) return;
  await sharp(srcPath)
    .rotate() // apply EXIF orientation before it gets stripped
    .resize({ width, withoutEnlargement: true })
    .webp({ quality: 82 })
    .toFile(outPath);
}

/** Responsive steps below the native size, plus the native size itself (capped) so the
 * largest generated copy is never meaningfully smaller than the source. */
function pickWidths(nativeWidth, steps, cap) {
  const capped = Math.min(nativeWidth ?? cap, cap);
  const widths = new Set(steps.filter((w) => w <= capped));
  widths.add(capped);
  return [...widths].sort((a, b) => a - b);
}

async function processPhotos() {
  await mkdir(PHOTOS_OUT, { recursive: true });
  const files = await listImages(PHOTOS_SRC);
  const manifest = [];

  for (const file of files) {
    const srcPath = path.join(PHOTOS_SRC, file);
    const id = slugify(file);
    const image = sharp(srcPath).rotate();
    const meta = await image.metadata();
    const rotated = (meta.orientation ?? 1) >= 5;
    const width = rotated ? meta.height : meta.width;
    const height = rotated ? meta.width : meta.height;

    const widths = pickWidths(width, PHOTO_WIDTHS, PHOTO_WIDTHS[PHOTO_WIDTHS.length - 1]);

    for (const w of widths) {
      const outPath = path.join(PHOTOS_OUT, `${id}-${w}.webp`);
      await renderSize(srcPath, outPath, w);
    }

    const { category, alt } = categorize(file);
    manifest.push({
      id,
      category,
      alt,
      width,
      height,
      widths,
      srcBase: `/photos/${id}`,
    });
  }

  return manifest;
}

async function processTripPages(orderedFiles) {
  await mkdir(TRIP_OUT, { recursive: true });
  const manifest = [];

  for (const { order, file, printedPage } of orderedFiles) {
    const srcPath = path.join(TRIP_SRC, file);
    const id = `page-${String(order).padStart(2, "0")}`;
    const meta = await sharp(srcPath).rotate().metadata();
    const rotated = (meta.orientation ?? 1) >= 5;
    const width = rotated ? meta.height : meta.width;
    const height = rotated ? meta.width : meta.height;

    const widths = pickWidths(width, TRIP_WIDTHS, TRIP_WIDTHS[TRIP_WIDTHS.length - 1]);

    for (const w of widths) {
      const outPath = path.join(TRIP_OUT, `${id}-${w}.webp`);
      await renderSize(srcPath, outPath, w);
    }

    manifest.push({
      id,
      order,
      printedPage,
      width,
      height,
      widths,
      srcBase: `/trip/${id}`,
    });
  }

  return manifest;
}

async function main() {
  // Raw sources are gitignored on purpose (see .gitignore) — a CI checkout or a fresh clone
  // without the original photos/ and teslas-trip/ folders won't have anything to process. In
  // that case the already-committed public/photos, public/trip, and manifest ARE the deployable
  // asset — leave them untouched rather than crashing (or worse, overwriting them with an empty
  // manifest).
  const hasPhotosSrc = await pathExists(PHOTOS_SRC);
  const hasTripSrc = await pathExists(TRIP_SRC);
  if (!hasPhotosSrc && !hasTripSrc) {
    console.log(
      "[process-images] no raw source folders found (photos/, teslas-trip/) — skipping " +
        "regeneration and using the already-committed public/ images as-is.",
    );
    return;
  }

  // Imported lazily (plain dynamic import of a .ts data file works under tsx/next, but this
  // script runs under plain Node) — the ordered list is duplicated here in sync with
  // src/data/trip-kabale.ts's kabaleOriginalPages; keep both in sync if the order ever changes.
  const orderedTripFiles = [
    { order: 1, printedPage: "Title page", file: "5DF7367A-2186-46DC-8247-B4C5D8881796.jpg" },
    { order: 2, printedPage: "Page 2", file: "4C72D10C-DE19-453B-A72B-5B8CA055596B.jpg" },
    { order: 3, printedPage: "Page 3", file: "25DA4056-468D-4147-8286-68FF95AEB576.jpg" },
    { order: 4, printedPage: "Page 4", file: "A2C0C7F7-81C8-4845-AC4E-EEE8B45DB30D.jpg" },
    { order: 5, printedPage: "Page 5", file: "0BFFBE33-9B62-4D88-9DFA-EEFA027B55D2.jpg" },
    { order: 6, printedPage: "Page 6", file: "BC0DA54D-212F-47C2-8A09-BB57305F1A92.jpg" },
    { order: 7, printedPage: "Page 7", file: "7C5BA684-872F-4C9B-9FE7-C964B4ABE7BA.jpg" },
    { order: 8, printedPage: "Page 8", file: "CB92CF04-8D28-4DEC-B5C8-96806A23E80B.jpg" },
    { order: 9, printedPage: "Page 9", file: "9E87F002-B7A8-4661-AFA0-74E8B55C00BD.jpg" },
    { order: 10, printedPage: "Page 10", file: "98A5E111-3F7D-4910-8AC8-7A381671DFE5.jpg" },
    { order: 11, printedPage: "Page 11", file: "7CF093D8-A1BC-4860-94A3-99E189B411B1.jpg" },
  ];

  const [photos, trip] = await Promise.all([
    processPhotos(),
    processTripPages(orderedTripFiles),
  ]);

  await mkdir(MANIFEST_DIR, { recursive: true });
  await writeFile(
    path.join(MANIFEST_DIR, "photo-manifest.json"),
    JSON.stringify({ photos, trip }, null, 2),
  );

  console.log(
    `[process-images] ${photos.length} gallery photos, ${trip.length} trip pages processed.`,
  );
}

main().catch((err) => {
  console.error("[process-images] failed:", err);
  process.exitCode = 1;
});
